func TestPromotionCommand(t *testing.T) {
	i := slices.Index(os.Args, "--")
	if i < 0 {
		return
	}
	kind, args := os.Args[i+1], os.Args[i+2:]
	fixture := os.Getenv("PROMOTE_FIXTURE")
	if fixture == "" {
		t.Fatal("missing fixture")
	}
	fail := func(message string) { fmt.Fprintln(os.Stderr, message); os.Exit(1) }
	appendLog := func(name, line string) {
		f, err := os.OpenFile(filepath.Join(fixture, name), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0600)
		if err != nil {
			fail(err.Error())
		}
		fmt.Fprintln(f, line)
		if err := f.Close(); err != nil {
			fail(err.Error())
		}
	}
	switch kind {
	case "gh":
		appendLog("gh-calls.log", strings.Join(args, " "))
		switch {
		case len(args) == 7 && slices.Equal(args[:2], []string{"release", "view"}) && args[3] == "--repo" && slices.Equal(args[5:], []string{"--json", "assets"}):
			dir := filepath.Join(fixture, "releases", strings.ReplaceAll(args[4], "/", "_"), args[2])
			entries, err := os.ReadDir(dir)
			if err != nil {
				fail(err.Error())
			}
			var assets []map[string]any
			for _, entry := range entries {
				info, err := entry.Info()
				if err != nil {
					fail(err.Error())
				}
				assets = append(assets, map[string]any{"name": entry.Name(), "size": info.Size()})
			}
			fmt.Println(string(jsonBytes(t, map[string]any{"assets": assets})))
		case (len(args) == 9 || len(args) == 10 && args[9] == "--clobber") && slices.Equal(args[:2], []string{"release", "download"}):
			source := filepath.Join(fixture, "releases", strings.ReplaceAll(args[4], "/", "_"), args[2], args[6])
			b, err := os.ReadFile(source)
			if err != nil {
				fail("asset not found: " + args[2] + "/" + args[6])
			}
			if err := os.WriteFile(args[8], b, 0600); err != nil {
				fail(err.Error())
			}
		case slices.Equal(args, []string{"api", "--hostname", "github.com", "repos/TerraScale/ts-orchestrator/actions/runs/11738"}):
			b, err := os.ReadFile(filepath.Join(fixture, "run-detail/11738.json"))
			if err != nil {
				fail(err.Error())
			}
			fmt.Println(string(b))
		case slices.Equal(args, []string{"api", "--hostname", "github.com", "--paginate", "--slurp", "repos/TerraScale/ts-orchestrator/actions/runs/11738/attempts/1/jobs?per_page=100"}):
			b, err := os.ReadFile(filepath.Join(fixture, "jobs/11738.json"))
			if err != nil {
				fail(err.Error())
			}
			fmt.Println(string(b))
		case slices.Equal(args, []string{"api", "--hostname", "github.com", "repos/TerraScale/ts-orchestrator/actions/jobs/25300/logs"}):
			b, err := os.ReadFile(filepath.Join(fixture, "logs/25300.txt"))
			if err != nil {
				fail(err.Error())
			}
			fmt.Println(string(b))
		default:
			fail(fmt.Sprintf("unexpected gh call: %q", args))
		}
	case "release":
		if args[0] != "release" {
			fail("expected unified release namespace")
		}
		args = args[1:]
		appendLog("release-calls.log", strings.Join(args, "\x00"))
		if os.Getenv("PROMOTE_FAIL_RELEASE") == args[0] {
			fail("fake " + args[0] + " rejected its inputs")
		}
		if args[0] == "verify-image-production" {
			if err := releasecli.Run(t.Context(), args, os.Stdout); err != nil {
				fail(err.Error())
			}
			os.Exit(0)
		}
		if j := slices.Index(args, "--out"); j >= 0 {
			// Like the real release tool, never overwrite an output.
			file, err := os.OpenFile(args[j+1], os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
			if err != nil {
				fail("create output without overwrite: " + err.Error())
			}
			if _, err := file.WriteString(`{"fake":"` + args[0] + `"}` + "\n"); err != nil {
				fail(err.Error())
			}
			if err := file.Close(); err != nil {
				fail(err.Error())
			}
		}
		if args[0] == "verify-image" {
			fmt.Println("verified OCI image=fake region=GRU")
		}
	default:
		fail("unexpected shim " + kind)
	}
	os.Exit(0)
}

