func TestDeployTool(t *testing.T) {
	i := slices.Index(os.Args, "--")
	if i < 0 {
		return
	}
	args := os.Args[i+1:]
	root, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	code := 2
	if len(args) > 0 {
		switch args[0] {
		case "image":
			var services image.Services
			// Promotion tests aim the real in-binary SDK importer at the
			// stand-in OCI region their parent process serves.
			if endpoint := os.Getenv(ociStandInEnv); endpoint != "" {
				services.ImageImporter = imageimporttest.Importer(endpoint)
			}
			code = image.RunWith(t.Context(), root, args[1:], os.Stdout, os.Stderr, services)
		case "netbird":
			code = client.Run(t.Context(), root, args[1:], os.Stdout, os.Stderr)
		}
	}
	os.Exit(code)
}

// ociStandInEnv carries the stand-in OCI endpoint from a test to the
// TestDeployTool subprocess. Only this test binary reads it.
const ociStandInEnv = "TS_TEST_OCI_STANDIN"

func deployTool(t *testing.T) string {
	t.Helper()
	exe, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(t.TempDir(), "ts-orch")
	write(t, path, []byte("#!/bin/sh\nGOMAXPROCS=2 GORACE=\"${GORACE:+$GORACE }atexit_sleep_ms=0\" exec "+shellQuote(exe)+" -test.run=^TestDeployTool$ -- \"$@\"\n"), 0755)
	return path
}

// runDeploy runs a deploy command. Its subprocesses (the offline builder,
// the promotion tool and this binary re-executed as ts-orch) read only
// repository files under deploy/: the pinned image inputs, systemd and udev
// units and the shell entry points. Tracking that tree alone keeps the
// suite's cached results valid across edits elsewhere; Go records every
// file the test process opens itself.
func runDeploy(t *testing.T, dir string, env map[string]string, name string, args ...string) script.Result {
	t.Helper()
	script.Track(t, "deploy")
	return script.Exec(t, dir, env, name, args...)
}

func runTool(t *testing.T, args ...string) script.Result {
	t.Helper()
	return runDeploy(t, deployRoot(t), nil, deployTool(t), args...)
}

func Exec(t *testing.T, dir string, env map[string]string, name string, args ...string) Result {
	t.Helper()
	ctx, cancel := context.WithTimeout(t.Context(), 3*time.Minute)
	defer cancel()
	cmd := exec.CommandContext(ctx, name, args...)
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Cancel = func() error { return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL) }
	cmd.WaitDelay = 2 * time.Second
	cmd.Dir = dir
	cmd.Env = os.Environ()
	for key, value := range env {
		prefix := key + "="
		for i := len(cmd.Env) - 1; i >= 0; i-- {
			if strings.HasPrefix(cmd.Env[i], prefix) {
				cmd.Env = append(cmd.Env[:i], cmd.Env[i+1:]...)
			}
		}
		cmd.Env = append(cmd.Env, prefix+value)
	}
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	err := cmd.Run()
	if ctx.Err() != nil {
		t.Fatalf("%s exceeded its command deadline: %v", name, ctx.Err())
	}
	code := 0
	if err != nil {
		if exit, ok := errors.AsType[*exec.ExitError](err); ok {
			code = exit.ExitCode()
		} else {
			t.Fatalf("start %s: %v", name, err)
		}
	}
	return Result{stdout.String(), stderr.String(), code}
}

netbird_install.text:
func LoadPin(path string) (Pin, error) {
	var inputs map[string]jsontext.Value
	b, err := os.ReadFile(path)
	if err != nil {
		return Pin{}, err
	}
	if err = json.Unmarshal(b, &inputs); err != nil {
		return Pin{}, err
	}
	raw, ok := inputs["netbird"]
	if !ok {
		return Pin{}, errors.New("missing NetBird input pin")
	}
	return ValidatePinJSON(raw)
}

func directDirectory(root, path string, mode os.FileMode, enforce bool) (string, error) {
	destination := root
	parts := strings.Split(strings.TrimPrefix(path, "/"), "/")
	for i, part := range parts {
		destination = filepath.Join(destination, part)
		s, e := os.Lstat(destination)
		if e == nil && !s.IsDir() {
			return "", fmt.Errorf("installation parent must be a direct directory: %s", destination)
		}
		if e != nil && !os.IsNotExist(e) {
			return "", e
		}
		if os.IsNotExist(e) {
			m := os.FileMode(0755)
			if i == len(parts)-1 {
				m = mode
			}
			if e = os.Mkdir(destination, m); e != nil {
				return "", e
			}
		}
	}
	if enforce {
		if e := os.Chmod(destination, mode); e != nil {
			return "", e
		}
	}
	return destination, nil
}
func installFile(source, destination string, mode os.FileMode) error {
	s, e := os.Lstat(destination)
	if e == nil && !s.Mode().IsRegular() {
		return fmt.Errorf("installation destination must be a direct file: %s", destination)
	}
	if e != nil && !os.IsNotExist(e) {
		return e
	}
	out, e := os.CreateTemp(filepath.Dir(destination), ".netbird-install-")
	if e != nil {
		return e
	}
	tmp := out.Name()
	out.Close()
	defer os.Remove(tmp)
	if e = copyFile(source, tmp, mode); e != nil {
		return e
	}
	return os.Rename(tmp, destination)
}

func Install(ctx context.Context, repo string, o InstallOptions, out io.Writer) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if o.Architecture == "" {
		return errors.New("unsupported host architecture")
	}
	root, e := filepath.EvalSymlinks(o.Root)
	if e != nil {
		return e
	}
	root, e = filepath.Abs(root)
	if e != nil {
		return e
	}
	live := root == "/"
	if live && os.Geteuid() != 0 {
		return errors.New("live NetBird installation must run as root")
	}
	if _, e = ValidateConfig(o.Config); e != nil {
		return e
	}
	pin, e := LoadPin(o.Inputs)
	if e != nil {
		return e
	}
	if e = VerifyBinary(o.EnrollBinary, o.EnrollSHA256, o.Architecture); e != nil {
		return e
	}
	work, e := os.MkdirTemp("", "ts-netbird-install-")
	if e != nil {
		return e
	}
	defer os.RemoveAll(work)
	binary := o.ClientBinary
	if binary == "" {
		binary = filepath.Join(work, "netbird")
		if e = Fetch(ctx, pin, o.Architecture, binary, o.Cache, nil); e != nil {
			return e
		}
	}
	a, e := pin.Archive(o.Architecture)
	if e != nil {
		return e
	}
	if e = VerifyBinary(binary, a.BinarySHA256, o.Architecture); e != nil {
		return e
	}
	systemctl := func(args ...string) error {
		cmd := exec.CommandContext(ctx, "systemctl", args...)
		b, e := cmd.CombinedOutput()
		if e != nil {
			return fmt.Errorf("systemctl %s: %s", strings.Join(args, " "), strings.TrimSpace(string(b)))
		}
		return nil
	}
	active := false
	if live {
		active = systemctl("is-active", "--quiet", "netbird.service") == nil
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	for _, path := range []string{"/usr/local/bin", "/usr/local/lib/terrascale-orchestrator", "/etc/terrascale-orchestrator", "/etc/systemd/system"} {
		if _, e = directDirectory(root, path, 0755, false); e != nil {
			return e
		}
	}
	if _, e = directDirectory(root, "/var/lib/netbird", 0700, true); e != nil {
		return e
	}
	for _, f := range []struct {
		src, dst string
		mode     os.FileMode
		digest   string
	}{{binary, "usr/local/bin/netbird", 0755, a.BinarySHA256}, {o.EnrollBinary, "usr/local/lib/terrascale-orchestrator/netbird-enroll", 0755, o.EnrollSHA256}, {o.Config, "etc/terrascale-orchestrator/netbird.json", 0644, ""}, {filepath.Join(repo, "deploy/systemd/netbird.service"), "etc/systemd/system/netbird.service", 0644, ""}, {filepath.Join(repo, "deploy/systemd/terrascale-netbird-enroll.service"), "etc/systemd/system/terrascale-netbird-enroll.service", 0644, ""}} {
		if f.digest != "" {
			e = installManagedBinary(f.src, filepath.Join(root, f.dst), f.digest, o.Architecture)
		} else {
			e = installFile(f.src, filepath.Join(root, f.dst), f.mode)
		}
		if e != nil {
			return e
		}
	}
	dropin, e := directDirectory(root, "/etc/systemd/system/terrascale-netbird-enroll.service.d", 0755, false)
	if e != nil {
		return e
	}
	override := filepath.Join(work, "command.conf")
	if e = os.WriteFile(override, []byte("[Service]\nExecStart=\nExecStart=/usr/local/lib/terrascale-orchestrator/netbird-enroll netbird-enroll --config /etc/terrascale-orchestrator/netbird.json\n"+
		"StateDirectory=terrascale-orchestrator/netbird-managed\nReadWritePaths=/usr/local/bin /var/lib/terrascale-orchestrator/netbird-managed\n"), 0644); e != nil {
		return e
	}
	if e = installFile(override, filepath.Join(dropin, "command.conf"), 0644); e != nil {
		return e
	}
	units := []string{"netbird.service", "terrascale-netbird-enroll.service"}
	if live {
		if e = systemctl("daemon-reload"); e != nil {
			return e
		}
		if e = systemctl(append([]string{"enable"}, units...)...); e != nil {
			return e
		}
		action := "start"
		if active {
			action = "restart"
		}
		if e = systemctl(action, units[0]); e != nil {
			return e
		}
		if e = systemctl("--no-block", "restart", units[1]); e != nil {
			return e
		}
	} else {
		wants, e := directDirectory(root, "/etc/systemd/system/multi-user.target.wants", 0755, false)
		if e != nil {
			return e
		}
		for _, name := range units {
			link := filepath.Join(wants, name)
			target := "../" + name
			if existing, e := os.Readlink(link); e == nil && existing == target {
				continue
			}
			if _, e = os.Lstat(link); e == nil {
				return fmt.Errorf("service enablement destination already exists: %s", link)
			} else if !os.IsNotExist(e) {
				return e
			}
			if e = os.Symlink(target, link); e != nil {
				return e
			}
		}
	}
	status := "enabled in offline root"
	if live {
		status = "started"
	}
	_, e = fmt.Fprintf(out, "NetBird %s installed; enrollment %s\n", pin.Version, status)
	return e
}

case "install":
	config := fs.String("config", "", "public config")
	enroll := fs.String("enroll-binary", "", "enrollment executable")
	sha := fs.String("enroll-sha256", "", "enrollment digest")
	binary := fs.String("client-binary", "", "pinned client")
	stage := fs.String("root", "/", "offline root")
	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return 0
		}
		return 2
	}
	if *config == "" || *enroll == "" || *sha == "" || fs.NArg() != 0 {
		return 2
	}
	e = Install(ctx, root, InstallOptions{*config, *enroll, *sha, *binary, *arch, *inputs, *cache, *stage}, stdout)

func installManagedBinary(source, destination, digest, architecture string) error {
	if info, err := os.Lstat(destination); err == nil && !info.Mode().IsRegular() {
		return errors.New("managed NetBird destination must be a direct regular file")
	} else if err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	file, err := os.CreateTemp(filepath.Dir(destination), ".netbird-managed-")
	if err != nil {
		return err
	}
	defer os.Remove(file.Name())
	defer file.Close()
	if err := copyFile(source, file.Name(), 0600); err != nil {
		return err
	}
	// The spool may change after its first verification. Verify the private
	// copy before making any bytes executable at the live service path.
	if err := VerifyBinary(file.Name(), digest, architecture); err != nil {
		return err
	}
	if err := file.Chmod(0755); err != nil {
		return err
	}
	err = errors.Join(file.Sync(), file.Close())
	if err != nil {
		return err
	}
	if err := os.Rename(file.Name(), destination); err != nil {
		return err
	}
	return syncManagedDirectory(filepath.Dir(destination))
}

