func promotionBuild(t *testing.T, unified bool, revision string, modified, failure bool) (string, map[string]any) {
	t.Helper()
	work := t.TempDir()
	calls := []any{}
	marker, contents := "cmd/ts-release/main.go", "#!/bin/sh\n[ \"$1\" = verify-binary ]\n"
	if unified {
		marker = "internal/release/cli/run.go"
		contents = "#!/bin/sh\n[ \"$1\" = release ] && [ \"$2\" = verify-binary ]\n"
	}
	runner := func(ctx context.Context, dir string, env []string, command ...string) (string, error) {
		args := make([]any, len(command))
		for i, a := range command {
			args[i] = a
		}
		calls = append(calls, map[string]any{"command": args, "cwd": dir})
		switch command[0] {
		case "git":
			if command[3] == "worktree" && command[4] == "add" {
				write(t, filepath.Join(work, "source", marker), []byte("pinned source entry point"), 0644)
			} else if command[3] == "worktree" && command[4] == "remove" {
				if err := os.RemoveAll(filepath.Join(work, "source")); err != nil {
					t.Fatal(err)
				}
			}
		case "nice":
			if failure {
				return "", errors.New("build failed")
			}
			path := command[slices.Index(command, "-o")+1]
			write(t, path, []byte(contents), 0755)
		case "go":
			return fmt.Sprintf("vcs.revision=%s\nvcs.modified=%t\n", revision, modified), nil
		default:
			return "", fmt.Errorf("unexpected command %q", command)
		}
		return "", nil
	}
	tool, prefix, record, err := image.BuildReleaseTool(t.Context(), deployRoot(t), work, promoteSource, "", runner)
	p := make([]any, len(prefix))
	for i, a := range prefix {
		p[i] = a
	}
	tools := map[string]any{}
	if record != nil {
		tools["ts_release"] = record
	}
	r := map[string]any{"calls": calls, "tool": tool, "prefix": p, "receipt": map[string]any{"tools": tools}, "error": nil}
	if err != nil {
		r["error"] = map[string]any{"message": err.Error()}
	}
	absent(t, filepath.Join(work, "source"))
	return work, r
}

func BuildReleaseTool(ctx context.Context, root, work, source, prebuilt string, run Exec) (tool string, prefix []string, record map[string]any, result error) {
	prefix = []string{"release"}
	if run == nil {
		run = Execute
	}
	if prebuilt != "" {
		tool, result = filepath.Abs(prebuilt)
		if result != nil {
			return
		}
	} else {
		if !gitSHA.MatchString(source) {
			result = errors.New("invalid image source revision")
			return
		}
		// go build runs inside the source worktree: a relative -o would
		// land in (and be removed with) that worktree.
		if work, result = filepath.Abs(work); result != nil {
			return
		}
		checkout := filepath.Join(work, "source")
		if _, result = run(ctx, "", nil, "git", "-C", root, "fetch", "--quiet", "origin", "main"); result != nil {
			return
		}
		if _, result = run(ctx, "", nil, "git", "-C", root, "worktree", "add", "--quiet", "--detach", checkout, source); result != nil {
			return
		}
		func() {
			defer func() {
				cleanupCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), time.Minute)
				defer cancel()
				_, cleanupErr := run(cleanupCtx, "", nil, "git", "-C", root, "worktree", "remove", "--force", checkout)
				result = errors.Join(result, cleanupErr)
			}()
			target := "./cmd/ts-release"
			name := "ts-release"
			prefix = []string{}
			if s, e := os.Stat(filepath.Join(checkout, "internal/release/cli/run.go")); e == nil && s.Mode().IsRegular() {
				target = "./cmd/terrascale-orchestrator"
				name = "ts-orch"
				prefix = []string{"release"}
			}
			tool = filepath.Join(work, name)
			_, result = run(ctx, checkout, nil, "nice", "-n", "19", "go", "build", "-trimpath", "-buildvcs=true", "-o", tool, target)
		}()
		if result != nil {
			return
		}
		var metadata string
		metadata, result = run(ctx, "", nil, "go", "version", "-m", tool)
		if result != nil {
			return
		}
		if !strings.Contains(metadata, "vcs.revision="+source) || !strings.Contains(metadata, "vcs.modified=false") {
			result = errors.New("release tool was not built from the clean image source revision")
			return
		}
	}
	s, e := os.Stat(tool)
	if e != nil || !s.Mode().IsRegular() || s.Mode().Perm()&0111 == 0 {
		result = fmt.Errorf("release tool is not executable: %s", tool)
		return
	}
	digest, e := fileHash(tool)
	if e != nil {
		result = e
		return
	}
	record = map[string]any{"path": tool, "sha256": digest}
	return
}

