func (f *promotionFixture) writeImage() {
	manifest := append(jsonBytes(f.t, f.manifest), '\n')
	sums := ""
	for _, asset := range []struct {
		name string
		data []byte
	}{{"terrascale-gru-arm64.qcow2", f.image}, {"guest-kernel", f.kernel}, {"image-qualification.json", manifest}} {
