// Requests returns every request served so far as "METHOD /path".
func (s *Server) Requests() []string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return slices.Clone(s.requests)
}

// Count returns how many served requests start with prefix.
func (s *Server) Count(prefix string) int {
	count := 0
	for _, request := range s.Requests() {
		if strings.HasPrefix(request, prefix) {
			count++
		}
	}
	return count
}

// Object returns a stored object's bytes and user metadata.
func (s *Server) Object(namespace, bucket, name string) ([]byte, map[string]string, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	stored, ok := s.objects[namespace+"/"+bucket+"/"+name]
	return stored.data, stored.metadata, ok
}

// Image returns the lifecycle state of a stored image.
func (s *Server) Image(id string) (string, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	for _, stored := range s.images {
		if stored.ID == id {
			return stored.State, true
		}
	}
	return "", false
}

func reply(w http.ResponseWriter, status int, value any) {
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("opc-request-id", "standin")
	w.WriteHeader(status)
	if value != nil {
		_ = json.MarshalWrite(w, value)
	}
}

func refuse(w http.ResponseWriter, status int, code, message string) {
	reply(w, status, map[string]string{"code": code, "message": message})

		if r.URL.Query().Get("page") == "" {
			w.Header().Set("opc-next-page", "global-schemas-2")
			reply(w, http.StatusOK, []map[string]string{})
			return
		}
		reply(w, http.StatusOK, []map[string]string{{"id": "ocid1.computeglobalimgcapschema.standin", "currentVersionName": "standin-v1"}})
	})
	mux.HandleFunc("GET "+core+"/images/{id}/shapes", s.listShapes)
	mux.HandleFunc("PUT "+core+"/images/{id}/shapes/{shape}", s.addShape)
	mux.HandleFunc("DELETE "+core+"/images/{id}/shapes/{shape}", s.removeShape)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Every SDK request is signed; an unsigned request is not the client
		// under test.
		if !strings.HasPrefix(r.Header.Get("Authorization"), "Signature ") {
			refuse(w, http.StatusUnauthorized, "NotAuthenticated", "unsigned request")
			return
		}
		s.mu.Lock()
		s.requests = append(s.requests, r.Method+" "+r.URL.Path)
		s.mu.Unlock()
		mux.ServeHTTP(w, r)
	})
}

func objectKey(r *http.Request) string {
	return r.PathValue("namespace") + "/" + r.PathValue("bucket") + "/" + r.PathValue("object")
}

func (s *Server) headObject(w http.ResponseWriter, r *http.Request) {
	s.mu.Lock()
	stored, ok := s.objects[objectKey(r)]
	s.mu.Unlock()
	if !ok {
		w.WriteHeader(http.StatusNotFound)
		return
	}
	for key, value := range stored.metadata {
		w.Header().Set("opc-meta-"+key, value)
	}
	w.Header().Set("Content-Length", fmt.Sprint(len(stored.data)))
	w.Header().Set("ETag", "standin")

	if want := r.Header.Get("Content-MD5"); want != "" && want != contentMD5(data) {
		refuse(w, http.StatusBadRequest, "InvalidContentMD5", "object MD5 mismatch")
		return
	}
	metadata := map[string]string{}
	for key, values := range r.Header {
		if name, ok := strings.CutPrefix(strings.ToLower(key), "opc-meta-"); ok && len(values) > 0 {
			metadata[name] = values[0]
		}
	}
	key := objectKey(r)
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, exists := s.objects[key]; exists && r.Header.Get("If-None-Match") == "*" {
		refuse(w, http.StatusPreconditionFailed, "IfNoneMatchFailed", "object exists")
		return
	}
	s.objects[key] = object{data: data, metadata: metadata}
	w.Header().Set("ETag", "standin")
	w.WriteHeader(http.StatusOK)
}

func (s *Server) find(id string) *image {
	for _, stored := range s.images {
		if stored.ID == id {
			return stored
		}
	}
	return nil
}

func (s *Server) listImages(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query()
	s.mu.Lock()
	defer s.mu.Unlock()
	matches := []image{}
	for _, stored := range s.images {
		if stored.CompartmentID == query.Get("compartmentId") && (query.Get("displayName") == "" || stored.DisplayName == query.Get("displayName")) {
			matches = append(matches, *stored)
		}
	}

		id = fmt.Sprintf("%s.%d", s.imageID, len(s.images))
	}
	created := &image{ID: id, CompartmentID: request.CompartmentID, DisplayName: request.DisplayName, State: "IMPORTING",
		Billable: BillableSizeGB, TimeCreated: s.created.Format(time.RFC3339), FreeformTags: request.FreeformTags}
	s.images = append(s.images, created)
	work := fmt.Sprintf("ocid1.coreservicesworkrequest.standin.%d", len(s.work)+1)
	s.work[work] = WorkRequestPolls
	s.workIDs[work] = id
	w.Header().Set("opc-work-request-id", work)
	reply(w, http.StatusOK, created)
}

func (s *Server) getImage(w http.ResponseWriter, r *http.Request) {
	s.mu.Lock()
	defer s.mu.Unlock()
	stored := s.find(r.PathValue("id"))
	if stored == nil {
		refuse(w, http.StatusNotFound, "NotAuthorizedOrNotFound", "image not found")
		return
	}
	reply(w, http.StatusOK, stored)
}

func (s *Server) getWorkRequest(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	s.mu.Lock()
	defer s.mu.Unlock()
	remaining, ok := s.work[id]
	if !ok {
		refuse(w, http.StatusNotFound, "NotAuthorizedOrNotFound", "work request not found")
		return
	}
	status := "SUCCEEDED"
	if remaining > 0 {
		status = "IN_PROGRESS"
		s.work[id] = remaining - 1
	} else if stored := s.find(s.workIDs[id]); stored != nil {
		stored.State = "AVAILABLE"
	}
	reply(w, http.StatusOK, map[string]any{"id": id, "operationType": "ImportImage", "status": status,
		"compartmentId": "standin", "percentComplete": 0, "timeAccepted": s.created.Format(time.RFC3339)})
}

func (s *Server) listSchemas(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query()
	s.mu.Lock()
	defer s.mu.Unlock()
	summaries := []map[string]string{}
	for _, stored := range s.schemas {
		if stored.CompartmentID == query.Get("compartmentId") && stored.ImageID == query.Get("imageId") {
			summaries = append(summaries, map[string]string{"id": stored.ID, "displayName": stored.DisplayName,
				"computeGlobalImageCapabilitySchemaVersionName": stored.Version, "timeCreated": stored.TimeCreated})
		}
	}
	reply(w, http.StatusOK, summaries)
}

func (s *Server) createSchema(w http.ResponseWriter, r *http.Request) {
	var request schema
	if err := json.UnmarshalRead(r.Body, &request); err != nil {
		refuse(w, http.StatusBadRequest, "InvalidParameter", err.Error())
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.find(request.ImageID) == nil {
		refuse(w, http.StatusNotFound, "NotAuthorizedOrNotFound", "image not found")
		return

	s.shapes[id] = slices.DeleteFunc(s.shapes[id], func(existing shape) bool { return existing.Shape == name })
	w.WriteHeader(http.StatusNoContent)
}

var signingKey = sync.OnceValues(func() (string, error) {
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		return "", err
	}
	return string(pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(key)})), nil
})

// Client returns the real in-binary SDK client for region, signing with a
// throwaway key and pinned to the stand-in at endpoint.
func Client(endpoint, region string) (imageimport.API, error) {
	key, err := signingKey()
	if err != nil {
		return nil, err
	}
	provider := common.NewRawConfigurationProvider("ocid1.tenancy.oc1..standin", "ocid1.user.oc1..standin", region,
		"00:00:00:00:00:00:00:00:00:00:00:00:00:00:00:00", key, nil)
	factory, err := ociclient.New(provider, ociclient.Options{Region: region,
		Retry: ociclient.RetryOptions{MaxAttempts: 1}})
	if err != nil {
		return nil, err
	}
	return imageimport.NewClient(factory, endpoint)
}

// Importer returns an ImporterFactory whose importers drive the real SDK
// client against the stand-in at endpoint, polling every millisecond.
func Importer(endpoint string) imageimport.ImporterFactory {
	return func(region string) (imageimport.Importer, error) {
		client, err := Client(endpoint, region)
		if err != nil {
			return imageimport.Importer{}, err
		}
		return imageimport.Importer{Client: client, PollInterval: time.Millisecond, MaxPollInterval: 5 * time.Millisecond,
			AvailabilityTimeout: time.Minute}, nil
	}
}

func RunImporters(ctx context.Context, args []string, out io.Writer, importers ImporterFactory) error {
	fs := flag.NewFlagSet("oci-region import-image", flag.ContinueOnError)
	fs.SetOutput(out)
	var o Options
	var regions regionList
	fs.StringVar(&o.QCOW2, "qcow2", "", "qualified QCOW2 file")
	fs.StringVar(&o.SHA256, "sha256", "", "expected QCOW2 SHA-256")
	fs.Var(&regions, "region", "catalog OCI region; repeatable or comma-separated (default "+catalog.OCIRegion(catalog.Bootstrap)+")")
	fs.StringVar(&o.Compartment, "compartment-id", "", "image compartment")
	fs.StringVar(&o.Namespace, "namespace", "", "object namespace")
	fs.StringVar(&o.Bucket, "bucket", "", "object bucket (same name in every region)")
	fs.StringVar(&o.DisplayName, "display-name", "", "image display name")
	fs.StringVar(&o.Out, "out", "", "output record")
	fs.IntVar(&o.PartSizeMiB, "part-size-mib", defaultPartSizeMiB, "multipart upload part size in MiB")
	fs.IntVar(&o.UploadParallelism, "upload-parallelism", defaultUploadParallelism, "concurrent multipart upload parts")
	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return nil
		}
		return err
	}
	if fs.NArg() != 0 {
		return fmt.Errorf("unexpected arguments: %v", fs.Args())
	}
	o.Regions = regions
	if len(o.Regions) == 0 {
		o.Regions = []string{catalog.OCIRegion(catalog.Bootstrap)}
	}
	_, err := ImportRegions(ctx, o, out, importers)
	return err
}

func ImportRegions(ctx context.Context, o Options, out io.Writer, importer func(region string) (Importer, error)) (map[string]any, error) {
	if ctx.Err() != nil {
		return nil, ctx.Err()
	}
	if err := o.validate(); err != nil {
		return nil, err
	}
	if err := verifyDigest(o.QCOW2, o.SHA256); err != nil {
		return nil, err
	}
	var (
		mu          sync.Mutex
		wg          sync.WaitGroup
		records     = make(map[string]map[string]any, len(o.Regions))
		errs        = make([]error, len(o.Regions))
		done        = make([]bool, len(o.Regions))
		checkpoints []error
	)
	result := func() map[string]any {
		if len(o.Regions) == 1 && records[o.Regions[0]] != nil {
			return records[o.Regions[0]]
		}
		regions := make(map[string]any, len(records))
		for region, record := range records {
			regions[region] = record
		}
		r := map[string]any{"schema": "terrascale.oci.image-import-set.v1", "qcow2_sha256": o.SHA256, "display_name": o.DisplayName, "regions": regions}
		failures := map[string]string{}
		var pending []string
		for index, region := range o.Regions {
			if !done[index] {
				pending = append(pending, region)
			}
			if errs[index] != nil {
				failures[region] = errs[index].Error()
			}
		}
		if len(failures) > 0 {
			r["errors"] = failures
		}
		if len(pending) > 0 {
			r["pending"] = pending
		}
		return r
	}
	if err := writeImportCheckpoint(o.Out, result()); err != nil {
		return nil, err
	}
	logf := func(format string, args ...any) {
		mu.Lock()
		defer mu.Unlock()
		_, _ = fmt.Fprintf(out, format, args...)
	}
	semaphore := make(chan struct{}, 3)
	for index, region := range o.Regions {
		semaphore <- struct{}{}
		wg.Go(func() {
			defer func() { <-semaphore }()
			var record map[string]any
			regional, err := importer(region)
			if err == nil {
				record, err = regional.importVerified(ctx, o, func(format string, args ...any) {
					if len(o.Regions) > 1 {
						format = region + ": " + format
					}
					logf(format, args...)
				})
			}
			mu.Lock()
			defer mu.Unlock()
			done[index] = true
			if err != nil {
				errs[index] = fmt.Errorf("%s: %w", region, err)
			} else {
				records[region] = record
			}
			if err := writeImportCheckpoint(o.Out, result()); err != nil {
				checkpoints = append(checkpoints, fmt.Errorf("checkpoint %s: %w", region, err))
			}
		})
	}
	wg.Wait()
	final := result()
	b, err := json.Marshal(final, json.Deterministic(true))
	if err != nil {
		return final, errors.Join(errors.Join(errs...), errors.Join(checkpoints...), err)
	}
	_, err = fmt.Fprintln(out, string(b))
	return final, errors.Join(errors.Join(errs...), errors.Join(checkpoints...), err)
}

func (i Importer) importVerified(ctx context.Context, o Options, logf func(string, ...any)) (map[string]any, error) {
	objectName := "images/" + o.SHA256 + ".qcow2"
	image, err := i.FindImage(ctx, o.Compartment, o.DisplayName)
	if err != nil {
		return nil, err
	}
	// Display names are static (gru-1-arm64), so a live image of this name
	// may hold another QCOW2. Resume only the import of these exact bytes.
	if image != nil && image.SHA256 != o.SHA256 {
		return nil, fmt.Errorf("live image %s is named %s but holds QCOW2 %q, not %s; retire it before importing",
			image.ID, o.DisplayName, image.SHA256, o.SHA256)
	}
	workRequest := ""
	if image == nil {
		exists, metadata, err := i.Client.HeadObject(ctx, o.Namespace, o.Bucket, objectName)
		if err != nil {
			return nil, err
		}
		if exists && metadata["sha256"] != "" && metadata["sha256"] != o.SHA256 {
			return nil, fmt.Errorf("object %s carries a different sha256 metadata value", objectName)
		}
		if !exists {
			logf("uploading %s\n", objectName)
			partSize := o.PartSizeMiB
			if partSize == 0 {
				partSize = defaultPartSizeMiB
			}
			parallelism := o.UploadParallelism
			if parallelism == 0 {
				parallelism = defaultUploadParallelism
			}
			if err := i.Client.UploadObject(ctx, UploadRequest{Namespace: o.Namespace, Bucket: o.Bucket, Object: objectName,
				Path: o.QCOW2, SHA256: o.SHA256, Metadata: map[string]string{"sha256": o.SHA256},
				PartSize: int64(partSize) << 20, Parallelism: parallelism}); err != nil {
				return nil, err
			}
		}
		logf("importing image\n")
		created, request, err := i.Client.ImportImage(ctx, ImportRequest{Compartment: o.Compartment, Namespace: o.Namespace,
			Bucket: o.Bucket, Object: objectName, DisplayName: o.DisplayName, SHA256: o.SHA256})
		if err != nil {
			return nil, err
		}
		image, workRequest = &created, request
	}
	if image.ID == "" {
		return nil, errors.New("OCI image has no id")
	}
	id := image.ID
	available, err := i.WaitAvailable(ctx, id, workRequest)
	if err != nil {
		return nil, err
	}
	schema, err := i.EnsureCapabilities(ctx, o.Compartment, id, o.DisplayName)
	if err != nil {
		return nil, err
	}
	shapes, err := i.EnsureShapes(ctx, id)
	if err != nil {
		return nil, err
	}
	names := make([]string, 0, len(shapes))
	for _, entry := range shapes {
		names = append(names, entry.Shape)
	}
	slices.Sort(names)
	var billable any
	if available.BillableSizeGB != nil {
		billable = *available.BillableSizeGB
	}
	return map[string]any{"schema": "terrascale.oci.image-import.v1", "image_id": id, "display_name": o.DisplayName,
		"qcow2_sha256": o.SHA256, "compartment_id": o.Compartment, "object": o.Namespace + "/" + o.Bucket + "/" + objectName,
		"billable_size_gb": billable, "capability_schema_id": schema.ID, "shapes": names}, nil
}

	return newSDKClient(factory, endpoint)
}

func newSDKClient(factory *ociclient.Factory, endpoint string) (*sdkClient, error) {
	compute, err := factory.Compute()
	if err != nil {
		return nil, err
	}
	objects, err := factory.ObjectStorage()
	if err != nil {
		return nil, err
	}
	work, err := factory.WorkRequests()
	if err != nil {
		return nil, err
	}
	ociclient.PinHost(&compute.BaseClient, endpoint)
	ociclient.PinHost(&objects.BaseClient, endpoint)
	ociclient.PinHost(&work.BaseClient, endpoint)
	return &sdkClient{compute: compute, objects: objects, workRequest: work,
		uploadRetry: ociclient.IdempotentPutRetryPolicy(ociclient.RetryOptions{})}, nil
}

	for range maxPages {
		response, err := c.compute.ListImages(ociclient.RequestContext(ctx), core.ListImagesRequest{CompartmentId: new(compartment),
			DisplayName: new(displayName), Page: cursor})
		if err != nil {
			return nil, fmt.Errorf("list OCI images: %w", err)
		}
		for _, item := range response.Items {
			images = append(images, image(item))
		}
		var more bool
		if cursor, more = page(response.OpcNextPage); !more {
			return images, nil
		}
	}
	return nil, errors.New("OCI image list exceeds its page bound")
}

func image(item core.Image) Image {
	return Image{ID: deref(item.Id), LifecycleState: string(item.LifecycleState), BillableSizeGB: item.BillableSizeInGBs,
		SHA256: item.FreeformTags[SHA256Tag]}
}

func deref(value *string) string {
	if value == nil {
		return ""
	}
	return *value
}

func (c *sdkClient) GetImage(ctx context.Context, id string) (Image, error) {
	response, err := c.compute.GetImage(ociclient.RequestContext(ctx), core.GetImageRequest{ImageId: new(id)})
	if err != nil {
		return Image{}, fmt.Errorf("get OCI image: %w", err)
	}
	return image(response.Image), nil
}

func (c *sdkClient) HeadObject(ctx context.Context, namespace, bucket, object string) (bool, map[string]string, error) {
	response, err := c.objects.HeadObject(ociclient.RequestContext(ctx), objectstorage.HeadObjectRequest{NamespaceName: new(namespace),
		BucketName: new(bucket), ObjectName: new(object)})
	if err != nil {
		if serviceErr, ok := common.IsServiceError(err); ok && serviceErr.GetHTTPStatusCode() == http.StatusNotFound {
			return false, nil, nil
		}
		return false, nil, fmt.Errorf("head OCI object: %w", err)
	}
	return true, response.OpcMeta, nil
}

func (c *sdkClient) UploadObject(ctx context.Context, request UploadRequest) error {
	return c.streamUpload(ctx, request)
}

func (c *sdkClient) ImportImage(ctx context.Context, request ImportRequest) (Image, string, error) {
	response, err := c.compute.CreateImage(ociclient.RequestContext(ctx), core.CreateImageRequest{
		CreateImageDetails: core.CreateImageDetails{
			CompartmentId: new(request.Compartment), DisplayName: new(request.DisplayName),
			FreeformTags: map[string]string{SHA256Tag: request.SHA256},
			LaunchMode:   core.CreateImageDetailsLaunchModeParavirtualized,
			ImageSourceDetails: core.ImageSourceViaObjectStorageTupleDetails{
				NamespaceName: new(request.Namespace), BucketName: new(request.Bucket), ObjectName: new(request.Object),
				SourceImageType: core.ImageSourceDetailsSourceImageTypeQcow2,
				OperatingSystem: new("Custom"), OperatingSystemVersion: new("Custom"),
			},
		},
		// A retry token lets the shared policy replay a lost CreateImage safely.
		OpcRetryToken: new(common.RetryToken()),
	})
	if err != nil {
		return Image{}, "", fmt.Errorf("import OCI image: %w", err)
	}
	return image(response.Image), deref(response.OpcWorkRequestId), nil
}

